concept.cypher:
MATCH (:Java:Artifact)-[:CONTAINS]->(declared:Java:Type)-[:EXTENDS]->(superType:Java:Type)
WITH declared.fqn AS fqn, collect(DISTINCT superType.fqn) AS superFqns, collect(superType)[0] AS resolvedSuper
// Only where every artifact declaring this type agrees on the super class.
// Two versions of a library disagreeing would otherwise be resolved by guess;
// measured on the production graph that affects 945 of 162612 names.
WHERE size(superFqns) = 1
MATCH (placeholder:Java:Type {fqn: fqn})
WHERE NOT (placeholder)-[:EXTENDS]->()
  AND NOT (:Java:Artifact)-[:CONTAINS]->(placeholder)
MERGE (placeholder)-[r:EXTENDS]->(resolvedSuper)
  ON CREATE SET r.jdkResolved = true
RETURN count(r) AS resolvedSuperClasses
